option_B_sop_vex.vex:
vector P2 = set(@P.x, @P.z, 0); // grille XZ de 4 m
vector per = {4,4,4};
f@R = pnoise(P2 * 40.0, per * 40.0); // ≈ 2,5 cm, ajouter 2 octaves (×2, ×4, amplitude ×0,5)
f@A = pnoise(P2 / 1.6, per / 1.6);
int seed; float f1, f2; vector p1, p2;
vnoise(P2 / 0.35, {0.9,0.9,0.9}, seed, f1, f2, p1, p2, per / 0.35); // version périodique de vnoise
f@B = clamp(1 - (f2 - f1) * 0.35 / 0.010, 0, 1);
f@G = random(seed);
